import random

# Each seed with the first float of the module's generator and 40 bits of a Random created from it.
CASES = [
    ((1 << 1) - 1, 0.13436424411240122, 623347347957),
    (-(1 << 0), 0.13436424411240122, 623347347957),
    ((1 << 1) // 3 + 1, 0.13436424411240122, 623347347957),
    ((1 << 31) - 1, 0.3177580158172969, 1027861944000),
    (-(1 << 30), 0.7947984595933472, 510219774322),
    ((1 << 31) // 3 + 1, 0.0860612148413199, 794938579862),
    ((1 << 32) - 1, 0.6353574441341173, 681333672201),
    (-(1 << 31), 0.3387958510019964, 413771977506),
    ((1 << 32) // 3 + 1, 0.29781370941097707, 486610404577),
    ((1 << 33) - 1, 0.8179491011186121, 1068664954034),
    (-(1 << 32), 0.11299430095636409, 382737396183),
    ((1 << 33) // 3 + 1, 0.0677828557641661, 983838635928),
    ((1 << 63) - 1, 0.3166448820870279, 722914485151),
    (-(1 << 62), 0.21122940420330605, 791181205853),
    ((1 << 63) // 3 + 1, 0.946235730449535, 983316594978),
    ((1 << 64) - 1, 0.021825695401270107, 270676680318),
    (-(1 << 63), 0.5534639983914199, 431873839368),
    ((1 << 64) // 3 + 1, 0.29781370941097707, 486610404577),
    ((1 << 65) - 1, 0.31055883375097393, 82938218660),
    (-(1 << 64), 0.9776462743838505, 811652810403),
    ((1 << 65) // 3 + 1, 0.0677828557641661, 983838635928),
    ((1 << 96) - 1, 0.3903770946264037, 774770770139),
    (-(1 << 95), 0.7434226087038013, 531473953199),
    ((1 << 96) // 3 + 1, 0.4345527615953725, 392708413840),
    ((1 << 1000) - 1, 0.9301673874400019, 442081702707),
    (-(1 << 999), 0.4259251151512262, 276707241394),
    ((1 << 1000) // 3 + 1, 0.38613868176538446, 615838776351),
    ((1 << 4999) - 1, 0.6389621158525496, 513845429625),
    (-(1 << 4998), 0.31694410414002283, 615541587889),
    ((1 << 4999) // 3 + 1, 0.3928362151960113, 306629896708),
    ((1 << 5000) - 1, 0.07881327072540956, 146367388507),
    (-(1 << 4999), 0.6608792012417435, 960616161555),
    ((1 << 5000) // 3 + 1, 0.4820218404355646, 298423011487),
    ((1 << 19968) - 1, 0.26632181641156105, 125697895074),
    (-(1 << 19967), 0.1739640765511249, 116711287016),
    ((1 << 19968) // 3 + 1, 0.06327434926481212, 438358425449),
    ((1 << 20000) - 1, 0.32156979753808823, 679985964538),
    (-(1 << 19999), 0.73404497768044, 170656423738),
    ((1 << 20000) // 3 + 1, 0.35099219245750346, 680112332744),
    (0, 0.8444218515250481, 424533559245),
    (True, 0.13436424411240122, 623347347957),
    (10 ** 100, 0.7319141759120473, 862137006626),
    (-(10 ** 100), 0.7319141759120473, 862137006626),
    ('', 0.9602256525641875, 502340344096),
    ('a', 0.2720295377534757, 555219139146),
    ('abcd', 0.3082803294348502, 443705685413),
    ('あいう', 0.3331716266698056, 843244551241),
    ('x' * 1000, 0.16324419727364425, 292758904615),
    ('y' * 4099, 0.25046882554313676, 769874901390),
    (0.0, 0.8444218515250481, 424533559245),
    (-0.0, 0.8444218515250481, 424533559245),
    (1.5, 0.551763726942059, 904312939308),
    (-1.5, 0.7101153317194698, 484086259294),
    (float('inf'), 0.19236379321481523, 301473906934),
    (123456789.125, 0.8670220597050131, 1077465655390),
]

for index, (seed, expected_float, expected_bits) in enumerate(CASES):
    random.seed(seed)
    actual = (random.random(), random.Random(seed).getrandbits(40))
    if actual != (expected_float, expected_bits):
        raise AssertionError(f"case {index}: {actual!r} != {(expected_float, expected_bits)!r}")

random.seed("abc", version=1)
if random.random() != 0.09639374978773074:
    raise AssertionError("version 1 seed of a str")
